'use strict';
// Explicit state fixtures: positioning and isolated elapsed-time setup are not legal routes.
const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),create=require('./route-harness-score1.cjs');
const source=fs.readFileSync(path.join(__dirname,'connected-inspection-b9f1a7b93ca1.html'),'utf8'),sourceHash=crypto.createHash('sha256').update(source).digest('hex'),cases=[];
let api,route;function load(level){({api,route}=create(source));api.newGame();api.loadLevel(level-1);api.startLevel();}
function use(n){Object.assign(api.player,{x:n.x-5,y:n.y-9,vx:0,vy:0,dead:0});api.keys.ArrowDown=false;api.updateCampaign();api.keys.ArrowDown=true;api.updateCampaign();api.keys.ArrowDown=false;api.updateCampaign();}
function test(name,fn){const detail=fn();cases.push({name,passed:true,detail});console.log('PASS '+name);}
test('Relay: returning retrieved anchored weight to its base preserves access and exactly one recoverable weight',()=>{load(6);const t=api.campaign.trials.find(t=>t.relay),n=id=>t.nodes.find(n=>n.id===id);use(n('1'));use(n('2'));use(n('3'));use(n('2'));use(n('1'));assert.equal(api.campaign.carry,null);assert.equal(t.docked,null);assert.ok(t.anchored&&t.bridges.every(b=>b.on));use(n('4'));assert.equal(t.solved,false);use(n('1'));assert.equal(api.campaign.carry,t.id);use(n('4'));assert.ok(t.solved);use(n('1'));assert.equal(api.campaign.carry,null);});
test('Clock: a wrong input at each partial stage clears all nodes and physical supports',()=>{for(const stage of [1,2]){load(6);const t=api.campaign.trials.find(t=>t.kind==='timed'&&t.bridges),n=id=>t.nodes.find(n=>n.id===id);use(n('1'));if(stage===2)use(n('2'));use(n('1'));assert.equal(t.progress,0);assert.equal(t.until,0);assert.ok(t.nodes.every(n=>!n.active));assert.ok(t.bridges.every(b=>!b.on&&api.tileAt(t.x0/16+b.col,b.row)==='.'));assert.equal(t.open,false);use(n('1'));assert.equal(t.progress,1);}});
test('Clock: expiry while standing on each stage-2 support drops onto safe floor without trapping the body',()=>{const results=[];for(const index of [1,2,3]){load(6);const t=api.campaign.trials.find(t=>t.kind==='timed'&&t.bridges),n=id=>t.nodes.find(n=>n.id===id);use(n('1'));use(n('2'));const b=t.bridges[index];Object.assign(api.player,{x:t.x0+(b.col+b.width/2)*16-5,y:b.row*16-18,vx:0,vy:0,onGround:true,energy:100});api.simF=t.until;route.input([0,0,0]);for(let i=0;i<100;i++)route.step();assert.equal(t.progress,0);assert.ok(api.player.onGround);assert.equal(api.player.y,142);assert.equal(api.player.dead,0);assert.equal(api.player.lives,3);use(n('1'));assert.equal(t.progress,1);results.push({bridge:index,lives:api.player.lives});}return results;});
test('Dual light: enumerate all 32 optical states before and after R; S cannot finish without history',()=>{load(7);const t=api.campaign.trials.find(t=>t.dualLight),turns=t.nodes.filter(n=>['mirror','prism'].includes(n.role)),results=[];for(const primed of [false,true]){let r=0,s=0,accepted=0;for(let mask=0;mask<32;mask++){t.primed=primed;turns.forEach((n,i)=>n.angle=(mask>>i)&1);const ok=api.mirrorTrace(t);if(t.lit==='R')r++;if(t.lit==='S')s++;if(ok)accepted++;if(!primed)assert.equal(ok,false);if(ok)assert.equal(t.lit,'S');}results.push({primed,r,s,accepted});}return results;});
test('Dual light: interrupted R charge and redirected S charge do not accumulate stale stable frames',()=>{load(7);const t=api.campaign.trials.find(t=>t.dualLight),n=id=>t.nodes.find(n=>n.id===id);n('B').angle=1;n('C').angle=0;for(let i=0;i<29;i++)api.updateCampaign();assert.equal(t.stable,29);assert.equal(t.primed,false);n('A').angle=0;api.updateCampaign();assert.equal(t.stable,0);n('A').angle=1;for(let i=0;i<30;i++)api.updateCampaign();assert.equal(t.primed,true);assert.equal(t.stable,0);n('E').angle=1;for(let i=0;i<29;i++)api.updateCampaign();assert.equal(t.stable,29);assert.equal(t.solved,false);n('E').angle=0;api.updateCampaign();assert.equal(t.stable,0);assert.ok(t.primed&&t.bridges.every(b=>b.on));n('E').angle=1;for(let i=0;i<30;i++)api.updateCampaign();assert.ok(t.solved);});
fs.writeFileSync(path.join(__dirname,'estados-conectados-b9f1a7b93ca1.json'),JSON.stringify({sourceHash,fixture:true,scope:'Isolated state fixtures, including direct node positioning/angle edits and one clock-time setup. These test engine recovery contracts, not human fairness or legal complete routes.',passed:cases.length,cases},null,2)+'\n');
